use crate::aap::caps::{http_client, state_read};

struct Node;

const SUBSCRIPTIONS_KEY: &str = "urls";
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Fetch the enrichment record for the input. RunInfo carries no free text,
/// so the query is built from its `date` field. The result is discarded:
/// enrichment is a side effect only and must not change the node's output.
/// A transport failure (`Err`) is likewise ignored.
fn enrich(info: &RunInfo) {
    let url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
    let _ = http_client::fetch(&url);
}

/// Read the subscription list from the `subscriptions` store: one URL per
/// line under the `urls` key. A missing key yields an empty list.
fn read_urls() -> Vec<String> {
    match state_read::get(SUBSCRIPTIONS_KEY) {
        Some(raw) => raw
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(String::from)
            .collect(),
        None => Vec::new(),
    }
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        enrich(&info);
        SubscriptionList { urls: read_urls() }
    }
}

export!(Node);
